```python
def build_pattern(ranges):
    """Output the regex pattern for ranges of characters.

    One and two character ranges output the individual characters.
    """
    out = []
    for a, b in ranges:
        if a == b:
            out.append(a)
        elif ord(b) - ord(a) == 1:
            out.append(a)
            out.append(b)
        else:
            out.append(f'{a}-{b}')
    return ''.join(out)
