/** Performs the actual opening and writing to a file. Basically cribbed from `java.nio.file.Files.write` so we could re-use it properly for different combinations of flags and all sorts of [[Source]]s */
def write(
    target: Path,
    data: Source,
    flags: Seq[StandardOpenOption],
    perms: PermSet,
    offset: Long
) = {
  checker.value.onWrite(target)

  import collection.JavaConverters._
  val permArray: Array[FileAttribute[_]] =
    if (perms == null) Array.empty
    else Array(PosixFilePermissions.asFileAttribute(perms.toSet()))

  val out = Files.newByteChannel(
    target.wrapped,
    flags.toSet.asJava,
    permArray: _*
  )
  out.position(offset)
  try data.writeBytesTo(out)
  finally if (out != null) out.close()
}
