final def pow(base: Long, exponent: Long): Long = {
  @tailrec def loop(t: Long, b: Long, e: Long): Long =
    if (e == 0L) t
    else if ((e & 1) == 1) loop(t * b, b * b, e >>> 1L)
    else loop(t, b * b, e >>> 1L)

