def check_heading_levels() -> None:
    """Headings start at level 1 and never skip a level."""
    heading_re = re.compile(r"^(#{1,6})\s|^<h([1-6])[\s>]")
    for file in sorted(glob.glob("**/*.md", recursive=True)):
