public fun parse(path: String): RoutingPath {
    if (path == "/") return root
    val segments = path.splitToSequence("/").filter { it.isNotEmpty() }.map { segment ->
        when {
            segment.contains('{') && segment.contains('}') -> RoutingPathSegment(
                segment,
                RoutingPathSegmentKind.Parameter
