function isVersionGte(version: string, minVersion: string): boolean {
  const core = parseVersionCore(version)
  const minCore = parseVersionCore(minVersion)
  for (let i = 0; i < 3; i++) {
    if (core[i] !== minCore[i]) return core[i] > minCore[i]
