fn print_paths_tree<W1, W2>(
    args: &Args,
    mut stdout: W1,
    mut stderr: W2,
    dir: &Path,
) -> Result<()>
where
    W1: io::Write,
    W2: io::Write,
{
    for result in args.walkdir(dir) {
        let dent = match result {
            Ok(dent) => dent,
            Err(err) => {
                if !args.ignore_errors {
                    writeln!(stderr, "ERROR: {}", err)?;
                }
                continue;
            }
        };
        stdout.write_all("  ".repeat(dent.depth()).as_bytes())?;
