    // Box the receiver if it is a primitive value
    if (!isPrimitiveValueType(receiver.tpe)) lhs0
    else makePrimitiveBox(lhs0, receiver.tpe)
  }

  js.BinaryOp(js.BinaryOp.String_+, lhs, rhs)
}
