export function makeWatcherCloseFinal(watcher: FSWatcher): FSWatcher {
  let closed = false
  const add = watcher.add
  watcher.add = function (...args: Parameters<FSWatcher['add']>) {
    if (closed) return this
    return add.apply(this, args)
