int uv_exepath(char* buffer, size_t* size) {
  char path[PATH_MAX];

  if (buffer == NULL || size == NULL || *size == 0)
    return UV_EINVAL;

  if (uv__getexecpath_init() == 0) {
    if (uv__getexecpath(path, sizeof path))
      return UV__ERR(errno);

    strlcpy(buffer, path, *size);
    *size = strlen(buffer);
