{
    var self    = this;
    var changes = TrieMap<EqK, K, Change<V>>.EmptyForMutating;
    foreach (var item in items)
    {
        var pair = self.AddOrUpdateWithLog(item.Key, item.Value);
        self = pair.Map;
        if (pair.Change.HasChanged)
