private fun String.toMaxAgeOrNull(): Int? {
    val digitsStart = if (startsWith('-')) 1 else 0
    if (digitsStart > lastIndex) return null
    for (index in digitsStart..lastIndex) {
        if (this[index] !in '0'..'9') return null
