/** Determines whether the key of a property in an object literal is a non-computed `__proto__`. `{ __proto__: foo }` and `{ "__proto__": foo }` set the object's prototype, while the concise forms `{ __proto__ }` and `{ __proto__() {} }` define an own property named `__proto__`, so converting between the two forms changes behavior in either direction. Computed keys are excluded because `{ ["__proto__"]: foo }` and `{ ["__proto__"]() {} }` both define an own property, which makes that conversion safe. */
function isProtoKey(property) {
	return (
		!property.computed &&
		astUtils.getStaticPropertyName(property) === "__proto__"
	);
}
